mapper.select:
select p.id productId, p.product_name productName, p.thumbnail, p.product_code productCode, p.product_desc productDesc, p.price, p.inventory , p.sold_orders soldOrders, p.warm_reminder warmReminder, p.status, p.create_at createAt from physical_product p
1=1 AND p.seller_brand_id = #{brandId}
AND (locate(#{dto.q}, p.product_name) > 0 or locate(#{dto.q}, p.product_code) > 0 or locate(#{dto.q}, p.product_desc) > 0)
AND p.status = #{dto.status}
order by p.create_at desc
